        #region Export Excel

        protected void btnExportExcel_Click(object sender, EventArgs e)
        {
            if (User == null)
            {
                MsgBox.ShowError("Bạn chưa đăng nhập hệ thống!");
                return;
            }

            if (uYearSemester.YearID == null || uYearSemester.Semester == null)
            {
                MsgBox.ShowError("Bạn phải chọn niên, kỳ!");
                return;
            }

            object scienceID = NormalizeFilterValue(uTeacher.ScienceID);
            if (!ValidateScienceRequired(scienceID))
                return;

            SIM_TeachingTimeAdded obj = new SIM_TeachingTimeAdded();
            DataTable dtbData = obj.GetDataTable("SIM_TeachingTimeAdded_Reviewed",
                                        "@YearID", uYearSemester.YearID,
                                        "@Semester", uYearSemester.Semester,
                                        "@ScienceID", scienceID,
                                        "@SubjectGroupID", NormalizeFilterValue(uTeacher.SubjectGroupID),
                                        "@TeacherID", NormalizeFilterValue(uTeacher.TeacherID));

            if (dtbData == null)
            {
                MsgBox.ShowError("Việc tải thông tin bị lỗi!");
                return;
            }

            if (dtbData.Rows.Count == 0)
            {
                MsgBox.ShowWarning("Không có dữ liệu để xuất!");
                return;
            }

            string sortExpression = null;
            if (this.SortBy != null && this.SortDesc != null)
                sortExpression = this.SortBy + " " + this.SortDesc;
            if (sortExpression != null && sortExpression != "")
                dtbData.DefaultView.Sort = sortExpression;

            DataTable dtbExport = dtbData.DefaultView.ToTable();

            StringBuilder sb = new StringBuilder();
            sb.Append("<html><head><meta http-equiv='Content-Type' content='text/html; charset=utf-8' /></head><body>");
            sb.Append("<table border='1'>");
            sb.Append("<tr>");
            sb.Append("<th>TT</th>");
            sb.Append("<th>Giảng viên</th>");
            sb.Append("<th>Công việc</th>");
            sb.Append("<th>Hệ số</th>");
            sb.Append("<th>Số lượng/Buổi</th>");
            sb.Append("<th>Quy đổi/ Số giờ (HC)</th>");
            sb.Append("<th>Số giờ chuẩn</th>");
            sb.Append("<th>Ghi chú/Nội dung</th>");
            sb.Append("<th>Hình thức</th>");
            sb.Append("<th>Đơn vị tổ chức</th>");
            sb.Append("<th>Thời gian</th>");
            sb.Append("<th>Các văn bản liên quan</th>");
            sb.Append("<th>Trạng thái duyệt</th>");
            sb.Append("<th>Ngày duyệt</th>");
            sb.Append("<th>Người duyệt</th>");
            sb.Append("<th>Ghi chú duyệt</th>");
            sb.Append("</tr>");

            int i = 1;
            foreach (DataRow drw in dtbExport.Rows)
            {
                sb.Append("<tr>");
                sb.AppendFormat("<td>{0}</td>", i++);
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "TeacherName"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "TeacherWorkName"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "Ratio"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "RequestQuantity"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "RequestTotal"));
                sb.AppendFormat("<td>{0}</td>", Server.HtmlEncode(GetStandardHours(GetVal(drw, "RequestTotal"), GetVal(drw, "TeacherWorkID"))));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "Description"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "Description1"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "Description2"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "Description3"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "Description4"));
                sb.AppendFormat("<td>{0}</td>", Server.HtmlEncode(FormatReviewStatusText(GetVal(drw, "IsReviewed"))));
                sb.AppendFormat("<td>{0}</td>", FormatDate(GetVal(drw, "ReviewedDate")));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "ReviewedUser"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "ReviewedComment"));
                sb.Append("</tr>");
            }

            sb.Append("</table></body></html>");

            string fileName = String.Format("DuyetCongViec_{0}.xls", DateTime.Now.ToString("yyyyMMdd_HHmmss"));
            Response.Clear();
            Response.Buffer = true;
            Response.ContentType = "application/vnd.ms-excel";
            Response.AddHeader("content-disposition", "attachment;filename=" + fileName);
            Response.Charset = "utf-8";
            Response.ContentEncoding = Encoding.UTF8;
            Response.Write(sb.ToString());
            Response.End();
        }

        private object GetVal(DataRow drw, string col)
        {
            if (drw.Table.Columns.Contains(col))
                return drw[col];
            return DBNull.Value;
        }

        private string HtmlVal(DataRow drw, string col)
        {
            object val = GetVal(drw, col);
            if (val == null || val == DBNull.Value)
                return "";
            return Server.HtmlEncode(val.ToString());
        }

        private string FormatDate(object value)
        {
            if (value == null || value == DBNull.Value)
                return "";
            try
            {
                return Convert.ToDateTime(value).ToString("dd/MM/yyyy");
            }
            catch
            {
                return Server.HtmlEncode(value.ToString());
            }
        }

        private string FormatReviewStatusText(object isReviewed)
        {
            if (IsTrue(isReviewed))
                return "Đã duyệt";
            return "Chưa duyệt";
        }

        #endregion
    }
